
.wallet-page-wrapper {
  width: 100%;
  min-height: 100vh;
  direction: rtl;
  padding: 20px 24px 24px;
  margin-top: 5px;
  box-sizing: border-box;
  overflow-x: hidden;
}


.wallet-container {
  width: 100%;
  max-width: 1500px;
  margin: 0 auto;
}

.wallet-main-row {
  align-items: stretch;
}

.wallet-mobile-header {
  display: none;
}

.wallet-main-card,
.wallet-history-card {
  width: 100%;
  height: auto;
  min-height: 0;
  border-radius: 20px;
  background: #ffffff;
  border: 1px solid #e9eef3;
  box-shadow: 0 8px 25px rgba(15, 23, 42, 0.06);
  box-sizing: border-box;
}

.wallet-main-card {
  padding: 16px;
}

.wallet-history-card {
  padding: 20px;
  display: flex;
  flex-direction: column;
}

.wallet-balance-box {
  width: 100%;
  background: linear-gradient(
    135deg,
    #16a34a 0%,
    #22c55e 50%,
    #15803d 100%
  );
  border-radius: 17px;
  padding: 20px;
  color: #ffffff;
  box-sizing: border-box;
}

.wallet-balance-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.wallet-balance-label {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 1.12rem;
}

.wallet-small-icon {
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.16);
  font-size: 0.95rem;
}

.wallet-status {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.14);
  font-size: 0.98rem;
}

.wallet-status svg {
  font-size: 0.85rem;
}

.wallet-balance-content {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 8px;
  padding: 20px 0 15px;
}

.wallet-balance-number {
  font-size: clamp(2rem, 3.8vw, 3rem);
  line-height: 1;
  letter-spacing: -1px;
}

.wallet-balance-currency {
  font-size: 0.95rem;
  opacity: 0.9;
}

.wallet-balance-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding-top: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.2);
  font-size: 0.86rem;
}

.wallet-balance-bottom svg {
  font-size: 0.85rem;
}

.wallet-deposit-section {
  padding: 18px 4px 2px;
}

.wallet-section-heading {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-bottom: 16px;
}

.wallet-section-icon {
  width: 38px;
  height: 38px;
  min-width: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  background: #ecfdf3;
  color: #16a34a;
  font-size: 0.95rem;
}

.wallet-section-heading h5 {
  margin: 0 0 3px;
  color: #17202a;
  font-size: 1.16rem;
  line-height: 1.4;
}

.wallet-section-heading p {
  margin: 0;
  color: #7b8794;
  font-size: 0.88rem;
  line-height: 1.5;
}

.wallet-suggested-section {
  margin-bottom: 14px;
}

.wallet-field-title {
  display: block;
  margin-bottom: 8px;
  color: #273444;
  font-size: 0.94rem;
}

.wallet-suggested-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 9px;
}

.wallet-suggested-btn {
  min-height: 58px;
  padding: 8px 6px;
  border: 1px solid #e4e9ee;
  border-radius: 11px;
  background: #f9fafb;
  color: #273444;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  transition: all 0.2s ease;
}

.wallet-suggested-btn:hover {
  background: #f0fdf4;
  border-color: #86efac;
  transform: translateY(-1px);
}

.suggested-amount {
  font-size: 0.94rem;
  line-height: 1.3;
  direction: ltr;
}

.suggested-label {
  font-size: 0.68rem;
  line-height: 1.3;
  color: #8a96a3;
}

.wallet-amount-group {
  margin-bottom: 13px;
}

.wallet-input-wrapper {
  position: relative;
  width: 100%;
}

.wallet-amount-input {
  width: 100%;
  height: 50px;
  border: 1px solid #dce3e8 !important;
  border-radius: 11px !important;
  background: #ffffff !important;
  padding: 8px 14px !important;
  padding-left: 50px !important;
  color: #17202a !important;
  font-size: 1.25rem !important;
  direction: ltr;
  text-align: right;
  box-shadow: none !important;
}

.wallet-amount-input::placeholder {
  color: #a1acb8 !important;
  font-size: 0.95rem !important;
}

.wallet-input-focused .wallet-amount-input {
  border-color: #22c55e !important;
  box-shadow: 0 0 0 3px rgba(34, 197, 94, 0.1) !important;
}

.wallet-input-unit {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  color: #64748b;
  font-size: 0.86rem;
  pointer-events: none;
}

.wallet-payment-btn {
  width: 100%;
  height: 48px;
  border: none !important;
  border-radius: 11px !important;
  background: #16a34a !important;
  display: flex !important;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 8px 14px !important;
  color: #ffffff !important;
  font-size: 0.99rem !important;
  box-shadow: 0 5px 15px rgba(22, 163, 74, 0.18);
  transition: all 0.2s ease;
}

.wallet-payment-btn:not(:disabled):hover {
  background: #15803d !important;
  transform: translateY(-1px);
}

.wallet-payment-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.wallet-payment-icon {
  display: flex;
  align-items: center;
  font-size: 0.9rem;
}

.wallet-payment-arrow {
  margin-right: auto;
  font-size: 1rem;
}

.wallet-history-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}

.wallet-history-title-wrapper {
  display: flex;
  align-items: center;
  gap: 11px;
}

.wallet-history-icon {
  width: 38px;
  height: 38px;
  min-width: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 11px;
  background: #f0fdf4;
  color: #16a34a;
  font-size: 0.95rem;
}

.wallet-history-title-wrapper h5 {
  margin: 0 0 3px;
  color: #17202a;
  font-size: 1.15rem;
}

.wallet-history-title-wrapper p {
  margin: 0;
  color: #8a96a3;
  font-size: 0.74rem;
}

.wallet-history-count {
  padding: 6px 10px;
  border-radius: 20px;
  background: #f4f7f8;
  color: #687585;
  font-size: 0.85rem;
  white-space: nowrap;
}

.wallet-history-divider {
  width: 100%;
  height: 1px;
  margin: 15px 0;
  background: #edf0f2;
}

.wallet-empty-state {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 15px 10px;
}

.wallet-empty-icon {
  width: 64px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 13px;
  border-radius: 50%;
  background: #f4f7f8;
  color: #a2adb8;
  font-size: 1.35rem;
}

.wallet-empty-state h3 {
  margin: 0 0 7px;
  color: #354052;
  font-size: 1.15rem;
}

.wallet-empty-state h5 {
  margin: 0;
  color: #8a96a3;
  font-size: 0.76rem;
  line-height: 1.8;
  opacity: 0.7;
}

@media (min-width: 1400px) {
  .wallet-page-wrapper {
    padding: 18px 28px 20px;
  }

  .wallet-main-card {
    padding: 17px;
  }

  .wallet-history-card {
