.wallet-mobile-wallet-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background: #ffc107;
  color: #111;
  padding: 6px 10px;
  border-radius: 9px;
  border: 1px solid #222;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s ease;
  font-family: inherit;
}

.wallet-mobile-wallet-btn:active {
  transform: scale(0.96);
}

.wallet-mobile-wallet-content {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.wallet-mobile-wallet-label {
  font-size: 15px;
}

.wallet-mobile-wallet-amount {
  font-size: 15px;
}

.wallet-mobile-wallet-icon {
  width: 19px;
  height: 19px;
  min-width: 19px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #ffc107;
  color: #111;
  border-radius: 50%;
}

.wallet-mobile-wallet-icon svg {
  font-size: 11px;
}

.wallet-mobile-wallet-btn:hover {
  background: rgba(255, 193, 7, 0.18);
  border-color: rgba(255, 193, 7, 0.55);
  color: #bd8b00;
}

.wallet-mobile-wallet-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  border-radius: 9px;
  background: rgba(255, 193, 7, 0.18);
}

.wallet-mobile-wallet-icon svg {
  flex-shrink: 0;
}

.wallet-mobile-wallet-content {
  display: flex;
