
.ticket-page { 
    width: 100%; 
    height: calc(100vh - 100px); 
    min-height: 0; 
    overflow-y: auto; 
    overflow-x: hidden; 
    direction: rtl; 
    padding: clamp(12px, 1.5vw, 20px); 
    box-sizing: border-box; 
} 
 
.ticket-page-wrapper { 
    width: 100%; 
    max-width: 1450px; 
    min-width: 0; 
    min-height: 100%; 
    margin: 0 auto; 
    padding-bottom: 18px; 
    box-sizing: border-box; 
} 
 
.ticket-page .row { 
    width: 100%; 
    margin-left: 0; 
    margin-right: 0; 
} 
 
.ticket-mobile-header { 
    display: none; 
} 
 
.ticket-mobile-header-inner { 
    width: 100%; 
    height: 100%; 
    display: flex; 
    align-items: center; 
    justify-content: space-between; 
    direction: rtl; 
    padding: 0 2px; 
} 
 
.ticket-mobile-menu-btn { 
    height: 39px; 
    min-width: 88px; 
    display: flex; 
    align-items: center; 
    justify-content: center; 
    gap: 8px; 
    padding: 0 10px; 
    border: 1px solid #e4e8e6; 
    border-radius: 11px; 
    background: #ffffff; 
    color: #26322d; 
    font-family: inherit; 
    font-size: 15px; 
    cursor: pointer; 
    box-shadow: 0 3px 9px rgba(35, 61, 48, 0.07); 
    transition: 
        transform 0.2s ease, 
        background 0.2s ease, 
        border-color 0.2s ease, 
        box-shadow 0.2s ease; 
    -webkit-tap-highlight-color: transparent; 
} 
 
.ticket-mobile-menu-btn:hover { 
    background: #f9fbfa; 
    border-color: #d7dfdb; 
    box-shadow: 0 4px 12px rgba(35, 61, 48, 0.09); 
} 
 
.ticket-mobile-menu-btn:active { 
    transform: scale(0.95); 
} 
 
.ticket-mobile-menu-btn:focus { 
    outline: none; 
    box-shadow: 0 3px 9px rgba(35, 61, 48, 0.07); 
} 
 
.ticket-mobile-menu-icon { 
    width: 29px; 
    height: 29px; 
    display: flex; 
    align-items: center; 
    justify-content: center; 
    border-radius: 8px; 
    background: #f0f5f2; 
    color: #26322d; 
} 
 
.ticket-mobile-menu-icon svg { 
    display: block; 
    flex-shrink: 0; 
} 
 
.ticket-mobile-menu-text { 
    line-height: 1; 
    font-size: 15px; 
} 
 
.ticket-mobile-page-title { 
    display: flex; 
    align-items: center; 
    gap: 10px; 
    color: #26322d; 
    font-family: inherit; 
    font-size: 18px; 
    white-space: nowrap; 
} 
 
.ticket-mobile-wallet-btn { 
    display: flex; 
    align-items: center; 
    justify-content: center; 
    gap: 6px; 
    background: #ffc107; 
    color: #111; 
    padding: 6px 10px; 
    border-radius: 9px; 
    border: 1px solid #222; 
    cursor: pointer; 
    white-space: nowrap; 
    transition: all 0.2s ease; 
    font-family: inherit; 
} 
 
.ticket-mobile-wallet-btn:hover { 
    background: rgba(255, 193, 7, 0.18); 
    border-color: #222; 
    color: #111; 
} 
 
.ticket-mobile-wallet-btn:active { 
    transform: scale(0.96); 
} 
 
.ticket-mobile-wallet-btn:focus { 
    outline: none; 
} 
 
.ticket-mobile-wallet-content { 
    display: flex; 
    align-items: center; 
    justify-content: center; 
    gap: 6px; 
} 
 
.ticket-mobile-wallet-label { 
    font-size: 15px; 
} 
 
.ticket-mobile-wallet-amount { 
    font-size: 15px; 
} 
 
.ticket-mobile-wallet-icon { 
    width: 19px; 
    height: 19px; 
    min-width: 19px; 
    display: flex; 
    align-items: center; 
    justify-content: center; 
    background: #ffc107; 
    color: #111; 
    border-radius: 50%; 
} 
 
.ticket-mobile-wallet-icon svg { 
    font-size: 11px; 
} 
 
.ticket-header { 
    width: 100%; 
    padding: clamp(16px, 1.6vw, 22px) clamp(18px, 2vw, 26px); 
    border-bottom: 1px solid #edf1f3; 
    background: linear-gradient(135deg, #ffffff, #f8fbf9); 
    box-sizing: border-box; 
} 
 
.ticket-header-main { 
    width: 100%; 
    display: flex; 
    align-items: center; 
    justify-content: space-between; 
    gap: 16px; 
} 
 
.ticket-header-text { 
    flex: 1; 
    min-width: 0; 
} 
 
.ticket-title-row { 
    display: flex; 
    align-items: center; 
    gap: 13px; 
} 
 
.ticket-title-row > div:last-child { 
    display: flex; 
    flex-direction: column; 
    gap: 5px; 
    min-width: 0; 
} 
 
.ticket-header-text h2 { 
    margin: 0; 
    font-size: clamp(20px, 1.6vw, 25px); 
    line-height: 1.5; 
    color: #1e293b; 
} 
 
.ticket-header-text span { 
    font-size: clamp(13px, 1vw, 15px); 
    line-height: 1.7; 
    color: #64748b; 
} 
 
.ticket-icon { 
    width: 48px; 
    height: 48px; 
    border-radius: 14px; 
    display: flex; 
    align-items: center; 
    justify-content: center; 
    background: #eaf7f0; 
    color: #198754; 
    font-size: 24px; 
    flex-shrink: 0; 
} 
 
.ticket-close-button { 
    width: 36px; 
    height: 36px; 
    border: 1px solid #e7edf0; 
    border-radius: 10px; 
    background: #ffffff; 
    color: #64748b; 
    display: flex; 
    align-items: center; 
    justify-content: center; 
    cursor: pointer; 
    font-size: 15px; 
    flex-shrink: 0; 
    transition: 0.2s ease; 
} 
 
.ticket-close-button:hover { 
    background: #fff5f5; 
    color: #dc3545; 
    border-color: #f0c8c8; 
} 
 
.ticket-content { 
    width: 100%; 
    padding: clamp(16px, 1.7vw, 22px); 
    box-sizing: border-box; 
} 
 
.ticket-row { 
    width: 100%; 
    margin: 0; 
} 
 
.ticket-section { 
    width: 100%; 
    height: 100%; 
    min-width: 0; 
    background: #ffffff; 
    border: 1px solid #e5ecef; 
    border-radius: 14px; 
    padding: clamp(15px, 1.5vw, 19px); 
    box-sizing: border-box; 
    transition: 0.2s ease; 
} 
 
.ticket-section:hover { 
    border-color: #c9ddd2; 
    box-shadow: 0 4px 14px rgba(25, 135, 84, 0.05); 
} 
 
.section-title { 
    width: 100%; 
    display: flex; 
    align-items: flex-start; 
    gap: 10px; 
    margin-bottom: 14px; 
} 
 
.section-number { 
    width: 29px; 
    height: 29px; 
    border-radius: 9px; 
    background: #198754; 
    color: #ffffff; 
    display: flex; 
    align-items: center; 
    justify-content: center; 
    flex-shrink: 0; 
    font-size: 14px; 
} 
 
.section-title h3 { 
    margin: 1px 0 0; 
    font-size: clamp(15px, 1.1vw, 17px); 
    line-height: 1.6; 
    color: #1e293b; 
} 
 
.section-title > div { 
    display: flex; 
    flex-direction: column; 
    gap: 4px; 
    min-width: 0; 
} 
 
.section-description { 
    color: #94a3b8; 
    font-size: clamp(12px, 0.9vw, 13px); 
    line-height: 1.7; 
} 
 
.ticket-section .form-label { 
    font-size: clamp(14px, 1vw, 15px); 
    line-height: 1.6; 
    color: #475569; 
    margin-bottom: 7px; 
} 
 
.required-mark { 
    color: #dc3545; 
    margin-right: 4px; 
} 
 
.ticket-section .form-control, 
.ticket-section .form-select { 
    width: 100%; 
    min-height: 43px; 
    height: auto; 
    border-radius: 10px; 
    border: 1px solid #dbe4e8; 
    box-shadow: none; 
    font-size: clamp(14px, 1vw, 15px); 
    line-height: 1.6; 
    text-align: right; 
    direction: rtl; 
    background-color: #ffffff; 
    padding: 9px 12px; 
    box-sizing: border-box; 
    transition: 0.2s ease; 
} 

.category-select-wrapper { 
    position: relative; 
    width: 100%; 
} 

.category-select-wrapper .category-select { 
    appearance: none; 
    -webkit-appearance: none; 
    -moz-appearance: none; 
    padding-left: 48px; 
    padding-right: 12px; 
    cursor: pointer; 
    background-image: none; 
} 

.category-select-wrapper .category-select:focus { 
    border-color: #198754; 
    box-shadow: 0 0 0 0.15rem rgba(25, 135, 84, 0.12); 
} 

.category-select-arrow { 
    position: absolute; 
    left: 13px; 
    top: 50%; 
    width: 30px; 
    height: 30px; 
    transform: translateY(-50%); 
    border-radius: 8px; 
    background: #f1f7f4; 
    display: flex; 
    align-items: center; 
    justify-content: center; 
    pointer-events: none; 
    transition: 0.2s ease; 
} 

.category-select-arrow span { 
    width: 7px; 
    height: 7px; 
    border-left: 2px solid #198754; 
    border-bottom: 2px solid #198754; 
    transform: rotate(-45deg) translateY(-2px); 
    transition: 0.2s ease; 
} 

.category-select-wrapper:hover .category-select-arrow { 
    background: #e6f4ec; 
} 

.category-select-wrapper:hover .category-select-arrow span { 
    transform: rotate(-45deg) translateY(1px); 
}
 
.ticket-section .form-control:focus, 
.ticket-section .form-select:focus { 
    border-color: #198754; 
    box-shadow: 0 0 0 0.15rem rgba(25, 135, 84, 0.12); 
} 
 
.priority-list { 
    width: 100%; 
    display: flex; 
    flex-direction: column; 
    gap: 7px; 
} 
 
.priority-item { 
    width: 100%; 
    min-height: 38px; 
    border-radius: 9px; 
    border: 1px solid #e2e8f0; 
    padding: 8px 11px; 
    display: flex; 
    align-items: center; 
    gap: 9px; 
    cursor: pointer; 
    transition: 0.2s ease; 
    box-sizing: border-box; 
} 
 
.priority-item:hover { 
    border-color: #b7d6c4; 
} 
 
.priority-item input { 
    display: none; 
} 
 
.priority-radio { 
    width: 16px; 
    height: 16px; 
    border-radius: 50%; 
    border: 2px solid #cbd5e1; 
    position: relative; 
    flex-shrink: 0; 
} 
 
.priority-low.active { 
    border-color: #198754; 
    background: #e8f7ee; 
} 
 
.priority-low.active .priority-radio { 
    border-color: #198754; 
} 
 
.priority-low.active .priority-radio::after { 
    content: ""; 
    width: 8px; 
    height: 8px; 
    border-radius: 50%; 
    background: #198754; 
    position: absolute; 
    top: 2px; 
    left: 2px; 
} 
 
.priority-low.active .priority-text { 
    color: #198754; 
} 
 
.priority-normal.active { 
    border-color: #f0ad00; 
    background: #fff8df; 
} 
 
.priority-normal.active .priority-radio { 
    border-color: #f0ad00; 
} 
 
.priority-normal.active .priority-radio::after { 
    content: ""; 
    width: 8px; 
    height: 8px; 
    border-radius: 50%; 
    background: #f0ad00; 
    position: absolute; 
    top: 2px; 
    left: 2px; 
} 
 
.priority-normal.active .priority-text { 
    color: #c48c00; 
} 
 
.priority-high.active { 
    border-color: #dc3545; 
    background: #fff0f1; 
} 
 
.priority-high.active .priority-radio { 
    border-color: #dc3545; 
} 
 
.priority-high.active .priority-radio::after { 
    content: ""; 
    width: 8px; 
    height: 8px; 
    border-radius: 50%; 
    background: #dc3545; 
    position: absolute; 
    top: 2px; 
    left: 2px; 
} 
 
.priority-high.active .priority-text { 
    color: #dc3545; 
} 
 
.priority-text { 
    font-size: clamp(14px, 1vw, 15px); 
    line-height: 1.6; 
    color: #475569; 
} 
 
.ticket-textarea { 
    min-height: 110px; 
    resize: vertical; 
    padding-top: 11px !important; 
    line-height: 1.9 !important; 
} 
 
.textarea-footer { 
    width: 100%; 
    display: flex; 
    align-items: center; 
    justify-content: space-between; 
    gap: 10px; 
    margin-top: 7px; 
    color: #94a3b8; 
    font-size: 12px; 
} 
 
.upload-box { 
    width: 100%; 
    min-height: 88px; 
    border: 1px dashed #b8c7cd; 
    border-radius: 13px; 
    background: #fafcfc; 
    display: flex; 
    align-items: center; 
    justify-content: center; 
    gap: 12px; 
    cursor: pointer; 
    padding: 13px; 
    color: #64748b; 
    box-sizing: border-box; 
    transition: 0.2s ease; 
} 
 
.upload-box:hover { 
    border-color: #198754; 
    background: #f4fbf7; 
} 
 
.upload-icon { 
    width: 39px; 
    height: 39px; 
    border-radius: 11px; 
    background: #ffffff; 
    border: 1px solid #e4ecef; 
    display: flex; 
    align-items: center; 
    justify-content: center; 
    color: #198754; 
    font-size: 18px; 
    flex-shrink: 0; 
} 
 
.upload-content { 
    display: flex; 
    flex-direction: column; 
    align-items: flex-start; 
    gap: 4px; 
    min-width: 0; 
} 
 
.upload-content span { 
    font-size: clamp(14px, 1vw, 15px); 
    line-height: 1.6; 
    color: #334155; 
} 
 
.upload-content small { 
    color: #94a3b8; 
    font-size: 12px; 
    line-height: 1.6; 
} 
 
.upload-clip { 
    font-size: 18px; 
    color: #cbd5e1; 
} 
 
.selected-file { 
    width: 100%; 
    min-height: 62px; 
    border-radius: 12px; 
    border: 1px solid #cce7d7; 
    background: #f3fbf7; 
    display: flex; 
    align-items: center; 
    gap: 11px; 
    padding: 10px 12px; 
    box-sizing: border-box; 
} 
 
.selected-file-icon { 
    width: 38px; 
    height: 38px; 
    border-radius: 10px; 
    display: flex; 
    align-items: center; 
    justify-content: center; 
    background: #ffffff; 
    color: #198754; 
    flex-shrink: 0; 
    font-size: 16px; 
} 
 
.selected-file-content { 
    flex: 1; 
    min-width: 0; 
    display: flex; 
    flex-direction: column; 
    gap: 3px; 
} 
 
.selected-file-content span { 
    color: #334155; 
    font-size: 14px; 
    line-height: 1.6; 
    overflow: hidden; 
    text-overflow: ellipsis; 
    white-space: nowrap; 
} 
 
.selected-file-content small { 
    color: #64748b; 
    font-size: 12px; 
    line-height: 1.5; 
} 
 
.remove-file-button { 
    width: 32px; 
    height: 32px; 
    border: 0; 
    border-radius: 9px; 
    background: #ffffff; 
    color: #dc3545; 
    display: flex; 
    align-items: center; 
    justify-content: center; 
    cursor: pointer; 
    flex-shrink: 0; 
    transition: 0.2s ease; 
} 
 
.remove-file-button:hover { 
    background: #fff1f1; 
} 
 
.ticket-footer { 
    width: 100%; 
    padding: 15px clamp(16px, 1.7vw, 22px) 18px; 
    border-top: 1px solid #edf1f3; 
    box-sizing: border-box; 
    background: #fcfdfd; 
} 
 
.submit-ticket-button, 
.cancel-button { 
    width: 100%; 
    min-height: 43px; 
    border-radius: 10px; 
    display: flex; 
    align-items: center; 
    justify-content: center; 
    gap: 8px; 
    cursor: pointer; 
    font-size: clamp(14px, 1vw, 15px); 
    line-height: 1.6; 
    transition: 0.2s ease; 
} 
 
.submit-ticket-button { 
    border: 0; 
    background: #198754; 
    color: #ffffff; 
    box-shadow: 0 4px 12px rgba(25, 135, 84, 0.13); 
} 
 
.submit-ticket-button:hover { 
    background: #157347; 
    transform: translateY(-1px); 
} 
 
.cancel-button { 
    border: 1px solid red; 
    background: red; 
    color: white; 
} 
 
.cancel-button:hover { 
    border-color: #b40113; 
    color: white; 
    background: #ac0000; 
} 


