    } 

    .ticket-mobile-menu-btn:hover { 
        background: #f9fbfa; 
        border-color: #d7dfdb; 
        box-shadow: 0 4px 12px rgba(35, 61, 48, 0.09); 
    } 

    .ticket-mobile-menu-btn:active { 
        transform: scale(0.95); 
    } 

    .ticket-mobile-menu-btn:focus { 
        outline: none; 
        box-shadow: 0 3px 9px rgba(35, 61, 48, 0.07); 
    } 

    .ticket-mobile-menu-icon { 
        width: 33px; 
        height: 33px; 
        display: flex; 
        align-items: center; 
        justify-content: center; 
        border-radius: 8px; 
        background: #f0f5f2; 
        color: #26322d; 
    } 

    .ticket-mobile-menu-icon svg { 
        display: block; 
        flex-shrink: 0; 
    } 

    .ticket-mobile-menu-text { 
        line-height: 1; 
        font-size: 18px; 
    } 

    .ticket-mobile-page-title { 
        display: flex; 
        align-items: center; 
        gap: 10px; 
        color: #26322d; 
        font-family: inherit; 
        font-size: 21px; 
        white-space: nowrap; 
    } 

    .ticket-mobile-wallet-btn { 
        display: flex; 
        align-items: center; 
        justify-content: center; 
        gap: 7px; 
        background: #ffc107; 
        color: #111; 
        padding: 8px 12px; 
        border-radius: 9px; 
        border: 1px solid #222; 
        cursor: pointer; 
        white-space: nowrap; 
        transition: all 0.2s ease; 
        font-family: inherit; 
    } 

    .ticket-mobile-wallet-btn:hover { 
        background: rgba(255, 193, 7, 0.18); 
        border-color: #222; 
        color: #111; 
    } 

    .ticket-mobile-wallet-btn:active { 
        transform: scale(0.96); 
    } 

    .ticket-mobile-wallet-btn:focus { 
        outline: none; 
    } 

    .ticket-mobile-wallet-content { 
        display: flex; 
        align-items: center; 
        justify-content: center; 
        gap: 7px; 
    } 

    .ticket-mobile-wallet-label { 
        font-size: 18px; 
    } 

    .ticket-mobile-wallet-amount { 
        font-size: 18px; 
    } 

    .ticket-mobile-wallet-icon { 
        width: 23px; 
        height: 23px; 
        min-width: 23px; 
        display: flex; 
        align-items: center; 
        justify-content: center; 
        background: #ffc107; 
        color: #111; 
        border-radius: 50%; 
    } 

    .ticket-mobile-wallet-icon svg { 
        font-size: 13px; 
    } 

    .ticket-page-wrapper { 
        width: 100%; 
        max-width: 100%; 
        min-height: 0; 
        margin: 0; 
        padding-bottom: 15px; 
    } 

    .ticket-content { 
        width: 100%; 
        padding: 10px 0; 
        box-sizing: border-box; 
    } 

    .ticket-row { 
        width: 100%; 
        margin: 0; 
        --bs-gutter-x: 0; 
        --bs-gutter-y: 12px; 
    } 

    .ticket-row > [class*="col-"] { 
        width: 100%; 
        padding-left: 0; 
        padding-right: 0; 
    } 

    .ticket-section { 
        width: 100%; 
        height: auto; 
        border-radius: 13px; 
        padding: 16px; 
    } 

    .section-title { 
        gap: 10px; 
        margin-bottom: 14px; 
    } 

    .section-number { 
        width: 34px; 
        height: 34px; 
        min-width: 34px; 
        border-radius: 9px; 
        font-size: 17px; 
    } 

    .section-title h3 { 
        font-size: 19px; 
        line-height: 1.9; 
    } 

    .section-description { 
        font-size: 16px; 
        line-height: 2; 
    } 

    .ticket-section .form-label { 
        font-size: 18px; 
        line-height: 1.9; 
        margin-bottom: 8px; 
    } 

.ticket-section .form-control, 
.ticket-section .form-select { 
    min-height: 52px; 
    border-radius: 10px; 
    font-size: 18px; 
    line-height: 1.9; 
    padding: 10px 13px; 
} 

.category-select-wrapper .category-select { 
    padding-left: 52px; 
    padding-right: 13px; 
} 

.category-select-arrow { 
    left: 13px; 
    width: 32px; 
    height: 32px; 
}
    .priority-list { 
        gap: 9px; 
    } 

    .priority-item { 
        min-height: 50px; 
        padding: 10px 12px; 
        border-radius: 9px; 
        gap: 10px; 
    } 

    .priority-radio { 
        width: 19px; 
        height: 19px; 
    } 

    .priority-text { 
        font-size: 18px; 
        line-height: 1.9; 
    } 

    .ticket-textarea { 
        min-height: 145px; 
        font-size: 18px !important; 
        line-height: 2.1 !important; 
    } 

    .textarea-footer { 
        margin-top: 7px; 
        font-size: 15px; 
        line-height: 1.8; 
    } 

    .upload-box { 
        min-height: 105px; 
        border-radius: 12px; 
        padding: 13px; 
        gap: 12px; 
    } 

    .upload-icon { 
        width: 44px; 
        height: 44px; 
        border-radius: 10px; 
        font-size: 20px; 
    } 

    .upload-content span { 
        font-size: 17px; 
        line-height: 1.9; 
    } 

    .upload-content small { 
        font-size: 15px; 
        line-height: 1.9; 
    } 

    .upload-clip { 
        font-size: 20px; 
    } 

    .selected-file { 
        min-height: 72px; 
        border-radius: 11px; 
        padding: 10px 12px; 
        gap: 10px; 
    } 

    .selected-file-icon { 
        width: 43px; 
        height: 43px; 
        border-radius: 10px; 
        font-size: 18px; 
    } 

    .selected-file-content span { 
        font-size: 17px; 
        line-height: 1.9; 
    } 

    .selected-file-content small { 
        font-size: 15px; 
        line-height: 1.8; 
    } 

    .remove-file-button { 
        width: 36px; 
        height: 36px; 
        border-radius: 9px; 
    } 

    .ticket-footer { 
        width: 100%; 
        padding: 12px 0 16px; 
        background: transparent; 
        border-top: 0; 
    } 

    .submit-ticket-button, 
    .cancel-button { 
        min-height: 52px; 
        border-radius: 10px; 
        font-size: 18px; 
        line-height: 1.8; 
    } 
} 


